  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import MapView from './MapView';

type Driver = {
  name: string;
  phone: string;
  email: string;
  currentLocation?: string;
};

type Order = {
  id: string;
  status: string;
  customer: string;
  fuelType: string;
  quantity: number;
  brand: string;
  price: number;
  deliveryAddress: string;
  timestamp: Date;
  estimatedDelivery?: Date;
  deliveredAt?: Date;
  paymentMethod?: string;
  driverName?: string;
  driver?: Driver;
};

const availableDrivers: Driver[] = [
