                        <div>
                          <p className="text-sm text-gray-400">Status</p>
                          <div className="flex items-center gap-2 mt-1">
                            {getStatusIcon(selectedOrder.status)}
                            {getStatusBadge(selectedOrder.status)}
                          </div>
                        </div>
                      </div>
                    </div>
                  </div>

                  {selectedOrder.status === 'pending' && (
                    <div className="mb-6 bg-slate-900 p-4 rounded-lg">
                      <h3 className="text-lg font-medium text-white mb-3">Assign Driver</h3>
                      <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
                        {availableDrivers.map((driver) => (
                          <div 
                            key={driver.name}
                            className={`p-4 rounded-lg cursor-pointer transition-colors ${
                              selectedDriver?.name === driver.name 
                                ? 'bg-orange-500 text-white' 
                                : 'bg-slate-800 hover:bg-slate-700'
                            }`}
                            onClick={() => setSelectedDriver(driver)}
                          >
                            <div className="flex items-center gap-2">
                              <User className="h-5 w-5" />
                              <p className="font-medium">{driver.name}</p>
                            </div>
                            <div className="mt-2 text-sm opacity-90">
                              <p className="flex items-center gap-1">
                                <Phone className="h-3 w-3" /> {driver.phone}
                              </p>
                              <p className="flex items-center gap-1">
                                <Truck className="h-3 w-3" /> {driver.currentLocation}
                              </p>
                            </div>
                          </div>
                        ))}
                      </div>
                    </div>
                  )}
                  
                  {selectedOrder.driver && (
                    <div className="mb-6 bg-slate-900 p-4 rounded-lg">
                      <h3 className="text-lg font-medium text-white mb-2">Delivery Driver</h3>
                      <div className="flex flex-col md:flex-row md:items-center md:justify-between">
                        <div className="flex items-center gap-3 mb-3 md:mb-0">
                          <div className="h-12 w-12 rounded-full bg-blue-500/10 flex items-center justify-center">
                            <User className="h-7 w-7 text-blue-500" />
                          </div>
                          <div>
                            <p className="font-medium text-white">{selectedOrder.driver.name}</p>
                            <p className="text-sm text-gray-400">{selectedOrder.driver.currentLocation}</p>
                          </div>
                        </div>
                        <div className="flex gap-2">
                          <Button variant="outline" size="sm" className="flex items-center gap-2 bg-slate-800">
                            <Phone className="h-4 w-4" />
                            {selectedOrder.driver.phone}
                          </Button>
                          <Button variant="outline" size="sm" className="flex items-center gap-2 bg-slate-800">
                            <Mail className="h-4 w-4" />
                            Contact
                          </Button>
                        </div>
                      </div>
                    </div>
                  )}
                  
                  <div className="mb-6">
                    <h3 className="text-lg font-medium text-white mb-3">Delivery Location</h3>
                    <div className="h-64 rounded-lg overflow-hidden border border-slate-700">
                      <MapView address={selectedOrder.deliveryAddress} />
                    </div>
                  </div>
                  
                  <div className="flex flex-wrap gap-3">
                    {selectedOrder.status === 'pending' && (
                      <>
                        <Button 
                          onClick={() => updateOrderStatus(selectedOrder.id, 'confirmed')}
                          className="bg-orange-500 hover:bg-orange-600 text-white"
                          disabled={!selectedDriver}
                        >
                          <Check className="mr-2 h-4 w-4" />
                          Confirm Order
                        </Button>
                        <Button 
                          variant="destructive" 
                          onClick={() => updateOrderStatus(selectedOrder.id, 'cancelled')}
                          className="bg-red-500 hover:bg-red-600"
                        >
                          <X className="mr-2 h-4 w-4" />
                          Reject Order
                        </Button>
                      </>
                    )}
                    
                    {selectedOrder.status === 'confirmed' && (
                      <Button 
                        onClick={() => updateOrderStatus(selectedOrder.id, 'in-transit')}
                        className="bg-orange-500 hover:bg-orange-600 text-white"
                      >
                        <Truck className="mr-2 h-4 w-4" />
                        Start Delivery
                      </Button>
                    )}
                    
                    {selectedOrder.status === 'in-transit' && (
                      <Button 
                        onClick={() => updateOrderStatus(selectedOrder.id, 'delivered')}
                        className="bg-green-500 hover:bg-green-600 text-white"
                      >
                        <Check className="mr-2 h-4 w-4" />
                        Mark as Delivered
                      </Button>
                    )}
                    
                    <Button variant="outline" className="bg-slate-900">
                      Contact Customer
                    </Button>
                  </div>
                </div>
              ) : (
                <div className="text-center py-12">
                  <AlertCircle className="h-12 w-12 text-gray-500 mx-auto mb-2" />
                  <p className="text-gray-400">Select an order to view details</p>
                </div>
              )}
            </CardContent>
          </Card>
        </div>
      </div>
    </div>
  );
};

export default FuelStationDashboard;

import React, { useState } from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { Settings, User, LogOut, Gift, Copy } from 'lucide-react';
import { LogoIcon } from '@/components/Logo';
import { Button } from '@/components/ui/button';
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { useIsMobile } from '@/hooks/use-mobile';
import { useAuth } from '@/contexts/AuthContext';
import { toast } from '@/components/ui/use-toast';
import BoardSwitcher from '@/components/BoardSwitcher';

const Header = () => {
  const location = useLocation();
  const navigate = useNavigate();
  const isMobile = useIsMobile();
  const { user, logout } = useAuth();
  const [showReferCode, setShowReferCode] = useState(false);

  const getInitials = (name: string) => {
    if (!name) return '';
    const nameParts = name.trim().split(' ');
    if (nameParts.length === 1) return nameParts[0][0].toUpperCase();
    return (nameParts[0][0] + nameParts[nameParts.length - 1][0]).toUpperCase();
  };

  const handleLogout = async () => {
    try {
      await logout();
      navigate('/login');
      toast({
        title: "Logged out successfully",
        description: "You have been logged out of your account.",
      });
    } catch (error) {
      toast({
        title: "Logout failed",
        description: "Failed to logout. Please try again.",
        variant: "destructive",
      });
    }
  };

  const handleCopyReferCode = () => {
    const referCode = `FUELMATE-${user?.id?.slice(0, 6).toUpperCase()}`;
    navigator.clipboard.writeText(referCode);
    toast({
      title: "Referral code copied!",
      description: "Share this code with your friends to earn rewards.",
    });
  };

  return (
    <header className="sticky top-0 z-50 w-full bg-slate-950 border-b border-slate-800 shadow-md">
      <div className="container flex items-center justify-between h-16 px-4 md:px-6">
        <div className="flex items-center gap-6">
          <Link to="/" className="flex items-center gap-2">
            <LogoIcon className="w-6 h-6 text-orange-500" />
            <span className="text-xl font-bold text-white">FuelMate</span>
          </Link>

          <BoardSwitcher />
        </div>

        <nav className="flex items-center gap-2 md:gap-4">
          <Link to="/settings">
            <Button variant="ghost" size="icon" className="text-white hover:bg-slate-800">
              <Settings className="w-5 h-5" />
              <span className="sr-only">Settings</span>
            </Button>
          </Link>

          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button variant="ghost" className="relative h-8 w-8 rounded-full">
                <Avatar className="h-8 w-8">
                  <AvatarImage src={user?.avatar} alt={user?.name} />
                  <AvatarFallback className="bg-slate-700 text-white">
                    {getInitials(user?.name || '')}
                  </AvatarFallback>
                </Avatar>
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent className="w-56 bg-slate-900 border-slate-800 text-white" align="end" forceMount>
              <div className="flex items-center justify-start gap-2 p-2">
                <div className="flex flex-col space-y-1 leading-none">
                  <p className="font-medium">{user?.name}</p>
                  <p className="w-[200px] truncate text-sm text-gray-400">
                    {user?.email}
                  </p>
                </div>
              </div>
              <DropdownMenuSeparator className="bg-slate-800" />
              <DropdownMenuItem asChild>
                <Link to="/profile" className="cursor-pointer">
                  <User className="mr-2 h-4 w-4" />
                  <span>Profile</span>
                </Link>
              </DropdownMenuItem>
              <DropdownMenuItem asChild>
                <Link to="/settings" className="cursor-pointer">
                  <Settings className="mr-2 h-4 w-4" />
                  <span>Settings</span>
                </Link>
              </DropdownMenuItem>
              <DropdownMenuItem
                className="cursor-pointer"
                onSelect={(e) => {
                  e.preventDefault();
                  setShowReferCode(!showReferCode);
                }}
              >
                <Gift className="mr-2 h-4 w-4" />
                <span>Refer & Earn</span>
              </DropdownMenuItem>
              {showReferCode && (
                <div className="p-2 bg-slate-800 m-2 rounded-md">
                  <p className="text-sm text-gray-400 mb-2">Your Referral Code:</p>
                  <div className="flex items-center gap-2">
                    <code className="text-orange-400 font-mono text-sm">
                      FUELMATE-{user?.id?.slice(0, 6).toUpperCase()}
                    </code>
                    <Button
                      variant="ghost"
                      size="icon"
                      className="h-6 w-6 text-gray-400 hover:text-white"
                      onClick={handleCopyReferCode}
                    >
                      <Copy className="h-3 w-3" />
                    </Button>
                  </div>
                </div>
              )}
              <DropdownMenuSeparator className="bg-slate-800" />
              <DropdownMenuItem
                className="cursor-pointer text-red-400 hover:text-red-300"
                onSelect={handleLogout}
              >
                <LogOut className="mr-2 h-4 w-4" />
                <span>Logout</span>
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        </nav>
      </div>
    </header>
  );
};

export default Header;

import React, { useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import OrderCard from './OrderCard';
import MapboxMap from './MapboxMap';
import { Phone, Mail, User, Search, MapPin, Clock, Truck, CheckCircle, AlertCircle } from 'lucide-react';
import { Input } from '@/components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Progress } from "@/components/ui/progress";

type Order = {
  id: string;
  status: 'pending' | 'confirmed' | 'in-transit' | 'delivered' | 'cancelled';
  fuelType: string;
  quantity: number;
  brand: string;
  price: number;
  deliveryAddress: string;
  timestamp: Date;
  estimatedDelivery?: Date;
  paymentMethod?: string;
  driver?: {
    name: string;
    phone: string;
    email: string;
    currentLocation?: string;
    coordinates?: { lat: number; lng: number };
  };
};

interface OrderTrackingProps {
  activeOrders: Order[];
  trackingOrderId: string | null;
  onTrackOrder: (orderId: string) => void;
}

const OrderTracking = ({ activeOrders, trackingOrderId, onTrackOrder }: OrderTrackingProps) => {
  const [selectedOrder, setSelectedOrder] = useState<Order | null>(null);

  const getDriverCoordinates = (order: Order | null) => {
    if (!order || order.status !== 'in-transit' || !order.driver) return null;
    
    if (order.driver.coordinates) {
      return order.driver.coordinates;
    }
    
    return { lat: 21.1702 + (Math.random() * 0.03), lng: 72.8311 + (Math.random() * 0.03) };
  };

  const getStatusProgress = (status: string): number => {
    switch (status) {
      case 'pending':
        return 25;
      case 'confirmed':
        return 50;
      case 'in-transit':
        return 75;
      case 'delivered':
        return 100;
      default:
        return 0;
    }
  };

  const getStatusSteps = (status: string) => {
    const steps = [
      { id: 'pending', label: 'Order Placed', icon: <Clock className="h-4 w-4" /> },
      { id: 'confirmed', label: 'Order Confirmed', icon: <CheckCircle className="h-4 w-4" /> },
      { id: 'in-transit', label: 'In Transit', icon: <Truck className="h-4 w-4" /> },
      { id: 'delivered', label: 'Delivered', icon: <CheckCircle className="h-4 w-4" /> },
    ];

    return steps.map((step, index) => {
      const isActive = steps.findIndex(s => s.id === status) >= index;
      return (
        <div key={step.id} className="flex items-center gap-2">
          <div className={`w-8 h-8 rounded-full flex items-center justify-center ${
            isActive ? 'bg-orange-500 text-white' : 'bg-slate-700 text-gray-400'
          }`}>
            {step.icon}
          </div>
          <div className={`text-sm ${isActive ? 'text-white' : 'text-gray-400'}`}>
            {step.label}
          </div>
        </div>
      );
    });
  };

  return (
    <Card className="bg-slate-900 border-slate-800">
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          <Truck className="h-5 w-5 text-orange-500" />
          Track Your Order
        </CardTitle>
      </CardHeader>
      <CardContent>
        <div className="mb-4">
          <Select
            value={trackingOrderId || ''}
            onValueChange={(value) => {
              onTrackOrder(value);
              const order = activeOrders.find(o => o.id === value);
              setSelectedOrder(order || null);
            }}
          >
