            </div>

            {selectedOrder.driver && (
              <div className="bg-slate-800 p-4 rounded-lg">
                <h3 className="text-lg font-medium text-white mb-3">Driver Information</h3>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
