            </div>

            <div className="flex gap-2">
              <Button className="flex-1 bg-orange-500 hover:bg-orange-600">
                Contact Support
              </Button>
              <Button variant="outline" className="flex-1">
                View Order Details
              </Button>
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );
};

