import { createContext, useContext, useState, ReactNode, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { toast } from "@/components/ui/use-toast";
import { api, User, AuthResponse, Order } from "@/services/api";

interface AuthContextType {
  isAuthenticated: boolean;
  isLoading: boolean;
  user: User | null;
  userOrders: Order[];
  login: (email: string, password: string) => Promise<void>;
  logout: () => Promise<void>;
  signup: (name: string, email: string, password: string) => Promise<void>;
  updateProfile: (data: Partial<User>) => Promise<void>;
  createOrder: (orderData: any) => Promise<Order>;
  getOrders: () => Promise<Order[]>;
  updateOrderStatus: (orderId: string, status: string, driver?: any) => Promise<Order>;
  loginAsGuest: () => Promise<void>;
  updatePassword: (currentPassword: string, newPassword: string) => Promise<void>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export function AuthProvider({ children }: { children: ReactNode }) {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [user, setUser] = useState<User | null>(null);
  const [userOrders, setUserOrders] = useState<Order[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const navigate = useNavigate();

  // Check for existing auth on mount
  useEffect(() => {
    const checkAuth = async () => {
      const token = localStorage.getItem('token');
      if (!token) {
        setIsLoading(false);
        return;
      }

      try {
        const user = await api.getProfile();
        setUser(user);
        setIsAuthenticated(true);
        // Also fetch orders if authenticated
        const orders = await api.getOrders();
        setUserOrders(orders);
      } catch (error) {
        console.error('Auth check failed:', error);
        localStorage.removeItem('token');
      }

      setIsLoading(false);
    };

    checkAuth();
  }, []);

  const login = async (email: string, password: string) => {
    try {
      const response = await api.login({ email, password });

      setUser(response.user);
      setIsAuthenticated(true);

      // Fetch orders after successful login
      const orders = await api.getOrders();
      setUserOrders(orders);

      toast({
        title: "Login successful",
        description: "Welcome back!",
      });

      navigate("/dashboard");
    } catch (error: any) {
      toast({
        title: "Login Failed",
        description: error.message || "An error occurred during login",
        variant: "destructive",
      });
      throw error;
    }
  };

  const logout = async () => {
    try {
      await api.logout();
    } catch (error) {
      console.error('Logout error:', error);
    } finally {
      setUser(null);
      setUserOrders([]);
      setIsAuthenticated(false);
      navigate("/auth");
    }
  };

  const signup = async (name: string, email: string, password: string) => {
    try {
      const response = await api.register({ name, email, password });

      setUser(response.user);
      setIsAuthenticated(true);

      toast({
        title: "Account created",
        description: "Your account has been created successfully!",
      });

      navigate("/dashboard");
    } catch (error: any) {
      toast({
        title: "Registration Failed",
        description: error.message || "An error occurred during registration",
        variant: "destructive",
      });
      throw error;
    }
  };

  const updateProfile = async (data: Partial<User>) => {
    try {
      const updatedUser = await api.updateProfile(data);

      // Update the local user state with the new data
      setUser(prev => ({
        ...prev,
        ...updatedUser
      }));

      // Ensure we're still marked as authenticated
      setIsAuthenticated(true);

      toast({
        title: "Profile updated",
        description: "Your profile has been updated successfully!",
      });

      // Optionally refresh orders if needed
      if (data.role || data.id) {
        const orders = await api.getOrders();
        setUserOrders(orders);
      }
    } catch (error: any) {
      // If it's an authentication error, try to refresh the session
      if (error.message.includes('unauthorized') || error.message.includes('invalid token')) {
        try {
          // Try to get the current user profile
          const currentUser = await api.getProfile();
          setUser(currentUser);
          setIsAuthenticated(true);

          // Retry the update
          return updateProfile(data);
        } catch (refreshError) {
          // If refresh fails, then we need to log in again
          toast({
            title: "Session expired",
            description: "Please log in again to continue.",
            variant: "destructive",
          });
          logout();
          return;
        }
      }

      toast({
        title: "Update failed",
        description: error.message || "An error occurred while updating your profile",
        variant: "destructive",
      });
      throw error;
    }
  };

  const createOrder = async (orderData: any) => {
    try {
      if (!isAuthenticated) {
        throw new Error('You must be logged in to place an order');
      }

      const newOrder = await api.createOrder(orderData);

      // Update local orders state
      setUserOrders(prev => [...prev, newOrder]);

      // Sync with window.orderSystem if it exists
      if (window.orderSystem) {
        window.orderSystem.addOrder({
          ...newOrder,
          id: newOrder._id,
          timestamp: new Date(newOrder.createdAt),
          status: newOrder.status || 'pending'
        });
      }

      return newOrder;
    } catch (error: any) {
      console.error('Error in createOrder:', error);
      throw error;
    }
  };

  const getOrders = async () => {
    try {
      if (user?.role === 'guest') {
        return [];
      }

      const orders = await api.getOrders();
      setUserOrders(orders);

      // Sync with window.orderSystem if it exists
      if (window.orderSystem) {
        window.orderSystem.orders = orders.map(order => ({
          ...order,
          id: order._id,
          timestamp: new Date(order.createdAt),
          estimatedDelivery: order.estimatedDelivery ? new Date(order.estimatedDelivery) : undefined,
        }));

        // Update order history for delivered orders
        const deliveredOrders = orders.filter(order => order.status === 'delivered');
        window.orderSystem.orderHistory = deliveredOrders.map(order => ({
          ...order,
          id: order._id,
          timestamp: new Date(order.createdAt),
          estimatedDelivery: order.estimatedDelivery ? new Date(order.estimatedDelivery) : undefined,
        }));

        window.orderSystem.listeners.forEach((callback: () => void) => callback());
      }

      return orders;
    } catch (error: any) {
      console.error('Error fetching orders:', error);
      toast({
        title: "Error",
        description: error.message || "Failed to fetch orders",
        variant: "destructive",
      });
      return [];
    }
  };

  const updateOrderStatus = async (orderId: string, status: string, driver?: any) => {
    try {
      const updatedOrder = await api.updateOrderStatus(orderId, status, driver);

      // Update local orders state
      setUserOrders(prev => prev.map(order =>
        order._id === orderId ? updatedOrder : order
      ));

      // Sync with window.orderSystem
      if (window.orderSystem) {
        const orderIndex = window.orderSystem.orders.findIndex(o => o.id === orderId);
        if (orderIndex !== -1) {
          window.orderSystem.orders[orderIndex] = {
            ...updatedOrder,
            id: updatedOrder._id,
            timestamp: new Date(updatedOrder.createdAt),
            estimatedDelivery: updatedOrder.estimatedDelivery ? new Date(updatedOrder.estimatedDelivery) : undefined,
          };

          if (status === 'delivered') {
            window.orderSystem.addToOrderHistory(window.orderSystem.orders[orderIndex]);
          }

          window.orderSystem.listeners.forEach((callback: () => void) => callback());
        }
      }

      return updatedOrder;
    } catch (error: any) {
      toast({
        title: "Error",
        description: error.message || "Failed to update order status",
        variant: "destructive",
      });
      throw error;
    }
  };

  const loginAsGuest = async () => {
    try {
      const guestUser = {
        id: 'guest',
        name: 'Guest User',
        email: 'guest@example.com',
        role: 'guest'
      };

      setUser(guestUser);
      setIsAuthenticated(true);

      toast({
        title: "Guest login successful",
        description: "Welcome! You are logged in as a guest.",
      });

      navigate("/dashboard");
    } catch (error: any) {
      toast({
        title: "Guest login failed",
        description: "An error occurred during guest login",
        variant: "destructive",
      });
      throw error;
    }
  };

  const updatePassword = async (currentPassword: string, newPassword: string) => {
    try {
      await api.updatePassword(currentPassword, newPassword);

      toast({
        title: "Password updated",
        description: "Your password has been changed successfully.",
      });
    } catch (error: any) {
      toast({
        title: "Password change failed",
        description: error.message || "An error occurred while changing your password",
        variant: "destructive",
      });
      throw error;
    }
  };

  const value = {
    isAuthenticated,
    isLoading,
    user,
    userOrders,
    login,
    logout,
    signup,
    updateProfile,
    createOrder,
    getOrders,
    updateOrderStatus,
    loginAsGuest,
    updatePassword,
  };

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error("useAuth must be used within an AuthProvider");
  }
  return context;
}

import * as React from "react"

import type {
  ToastActionElement,
  ToastProps,
} from "@/components/ui/toast"

const TOAST_LIMIT = 1
const TOAST_REMOVE_DELAY = 1000000

type ToasterToast = ToastProps & {
  id: string
  title?: React.ReactNode
  description?: React.ReactNode
  action?: ToastActionElement
}

const actionTypes = {
  ADD_TOAST: "ADD_TOAST",
  UPDATE_TOAST: "UPDATE_TOAST",
  DISMISS_TOAST: "DISMISS_TOAST",
  REMOVE_TOAST: "REMOVE_TOAST",
} as const

let count = 0

function genId() {
  count = (count + 1) % Number.MAX_SAFE_INTEGER
  return count.toString()
}

type ActionType = typeof actionTypes

type Action =
  | {
      type: ActionType["ADD_TOAST"]
      toast: ToasterToast
    }
  | {
      type: ActionType["UPDATE_TOAST"]
      toast: Partial<ToasterToast>
    }
  | {
      type: ActionType["DISMISS_TOAST"]
      toastId?: ToasterToast["id"]
    }
  | {
      type: ActionType["REMOVE_TOAST"]
      toastId?: ToasterToast["id"]
    }

interface State {
  toasts: ToasterToast[]
}

const toastTimeouts = new Map<string, ReturnType<typeof setTimeout>>()

const addToRemoveQueue = (toastId: string) => {
  if (toastTimeouts.has(toastId)) {
    return
  }

  const timeout = setTimeout(() => {
    toastTimeouts.delete(toastId)
    dispatch({
      type: "REMOVE_TOAST",
      toastId: toastId,
    })
  }, TOAST_REMOVE_DELAY)

  toastTimeouts.set(toastId, timeout)
}

export const reducer = (state: State, action: Action): State => {
  switch (action.type) {
    case "ADD_TOAST":
      return {
        ...state,
        toasts: [action.toast, ...state.toasts].slice(0, TOAST_LIMIT),
      }

    case "UPDATE_TOAST":
      return {
        ...state,
        toasts: state.toasts.map((t) =>
          t.id === action.toast.id ? { ...t, ...action.toast } : t
        ),
      }

    case "DISMISS_TOAST": {
      const { toastId } = action

      // ! Side effects ! - This could be extracted into a dismissToast() action,
      // but I'll keep it here for simplicity
      if (toastId) {
        addToRemoveQueue(toastId)
      } else {
        state.toasts.forEach((toast) => {
          addToRemoveQueue(toast.id)
        })
      }

      return {
        ...state,
        toasts: state.toasts.map((t) =>
          t.id === toastId || toastId === undefined
            ? {
                ...t,
                open: false,
              }
            : t
        ),
      }
    }
    case "REMOVE_TOAST":
      if (action.toastId === undefined) {
        return {
          ...state,
          toasts: [],
        }
      }
      return {
        ...state,
        toasts: state.toasts.filter((t) => t.id !== action.toastId),
      }
  }
}

const listeners: Array<(state: State) => void> = []

let memoryState: State = { toasts: [] }

function dispatch(action: Action) {
  memoryState = reducer(memoryState, action)
  listeners.forEach((listener) => {
    listener(memoryState)
  })
}

type Toast = Omit<ToasterToast, "id">

function toast({ ...props }: Toast) {
  const id = genId()

  const update = (props: ToasterToast) =>
    dispatch({
      type: "UPDATE_TOAST",
      toast: { ...props, id },
    })
  const dismiss = () => dispatch({ type: "DISMISS_TOAST", toastId: id })

  dispatch({
    type: "ADD_TOAST",
    toast: {
      ...props,
      id,
      open: true,
      onOpenChange: (open) => {
        if (!open) dismiss()
      },
    },
  })

  return {
    id: id,
    dismiss,
    update,
  }
}

function useToast() {
  const [state, setState] = React.useState<State>(memoryState)

  React.useEffect(() => {
    listeners.push(setState)
    return () => {
      const index = listeners.indexOf(setState)
      if (index > -1) {
        listeners.splice(index, 1)
      }
    }
  }, [state])

  return {
    ...state,
    toast,
    dismiss: (toastId?: string) => dispatch({ type: "DISMISS_TOAST", toastId }),
  }
}

export { useToast, toast }

import { useState, useEffect } from "react";
