  const handleLogin = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setIsLoading(true);
    setLoginError("");

    // Simulate login process and redirect to under construction
    setTimeout(() => {
      setIsLoading(false);
      navigate("/under-construction", { replace: true });
    }, 1000);
  };

